// ChildMessage component (child.component.ts)
import { Component, Input, Output, EventEmitter } from '@angular/core';

@Component({
  selector: 'app-child-message',
  template: `
    <div>
      <h3>Child says:</h3>
      <p>{{ incomingMessage }}</p>
      <button (click)="reply()">Reply</button>
    </div>
  `
})
export class ChildMessageComponent {
  @Input() incomingMessage: string = '';
  @Output() replyEvent = new EventEmitter<string>();

  reply() {
    this.replyEvent.emit('Hello back from child!');
  }
}

// AppComponent (parent)
export class AppComponent {
  parentMessage = 'Hello from parent';
  reply = '';

  receiveReply(msg: string) {
    this.reply = msg;
  }
}

// app.component.html
<app-child-message
  [incomingMessage]="parentMessage"
  (replyEvent)="receiveReply($event)">
</app-child-message>
<p *ngIf="reply">Parent received: {{ reply }}</p>
